<?php

/**
 * Lets a WidgetEditor (v2) widget delegate to a v1 widget (D13)
 *
 * The bridge keeps the v1 class doing the work: its render(), editor form, assets, callbacks and metadata are
 * used as they are. Only the v2 surface is mapped onto them. A bridge is generated by `cms:widgets:bridge`, one
 * class per legacy widget, so an app can review the list before any of it is used. It is for app widgets; the
 * widgets modules ship are native v2 classes.
 *
 * @package     Nails
 * @subpackage  module-cms
 * @category    Trait
 * @author      Nails Dev Team
 */

namespace Nails\Cms\WidgetEditor\Traits;

use Nails\Cms\Constants;
use Nails\Cms\WidgetEditor\Status;
use Nails\Factory;

trait Legacy
{
    /** One v1 instance per class, for the life of the request */
    private static array $legacyInstances = [];

    // --------------------------------------------------------------------------

    /**
     * The v1 widget class to delegate to. This is the leaf class, so an app override is returned when there is one.
     */
    abstract protected static function legacyClass(): string;

    // --------------------------------------------------------------------------

    /**
     * The v1 class, loaded. v1 widgets are defined by their widget.php files, which only the v1 widget service
     * requires, so a bridge that is used before the v1 service has run loads them through it.
     *
     * @throws \RuntimeException
     */
    protected static function legacy(): string
    {
        $sClass = static::legacyClass();

        if (!class_exists($sClass)) {
            Factory::service('Widget', Constants::MODULE_SLUG)->getAvailable(true);
        }

        if (!class_exists($sClass)) {
            throw new \RuntimeException('Legacy widget class "' . $sClass . '" does not exist');
        }

        return $sClass;
    }

    // --------------------------------------------------------------------------

    /**
     * The slug the v1 widget was stored under: the name of its folder, as Cms\Widget\WidgetBase detects it.
     */
    protected static function legacySlug(): string
    {
        return basename(dirname((new \ReflectionClass(static::legacy()))->getFileName()));
    }

    // --------------------------------------------------------------------------

    /**
     * The v1 instance, created the first time it is needed. Its constructor reads files, so it is not created
     * until a method of the bridge is called.
     */
    protected function legacyWidget(): object
    {
        $sClass = static::legacy();
        return self::$legacyInstances[$sClass] ??= new $sClass();
    }

    // --------------------------------------------------------------------------

    /**
     * Stored content keeps the v1 slug, so it resolves through an alias
     */
    public static function getAliases(): array
    {
        return array_values(array_unique(array_merge([static::legacySlug()], static::ALIASES)));
    }

    // --------------------------------------------------------------------------

    /**
     * Disabled, deprecated and hidden map to the v2 statuses, in that order of precedence
     */
    public static function getStatus(): Status
    {
        $sClass = static::legacy();

        if ($sClass::isDisabled()) {
            return Status::DISABLED;
        } elseif ($sClass::isDeprecated()) {
            return Status::DEPRECATED;
        } elseif ($sClass::isHidden()) {
            return Status::HIDDEN;
        }

        return Status::ACTIVE;
    }

    // --------------------------------------------------------------------------

    public static function getAlternative(): ?string
    {
        $sAlternative = static::legacy()::alternative();
        return $sAlternative !== '' ? $sAlternative : null;
    }

    // --------------------------------------------------------------------------

    public function getLabel(): string
    {
        return (string) $this->legacyWidget()->getLabel();
    }

    // --------------------------------------------------------------------------

    /** v1 has one description, which is used as both the summary and the description */
    public function getSummary(): string
    {
        return (string) $this->legacyWidget()->getDescription();
    }

    // --------------------------------------------------------------------------

    public function getDescription(): string
    {
        return (string) $this->legacyWidget()->getDescription();
    }

    // --------------------------------------------------------------------------

    public function getIcon(): string
    {
        return (string) $this->legacyWidget()->getIcon();
    }

    // --------------------------------------------------------------------------

    /** v1 has one grouping, which becomes the one group of the widget */
    public function getGroups(): array
    {
        $sGrouping = trim((string) $this->legacyWidget()->getGrouping());
        return $sGrouping === '' ? [] : [$sGrouping];
    }

    // --------------------------------------------------------------------------

    /** v1 keywords are a comma separated string */
    public function getKeywords(): array
    {
        $aKeywords = array_map('trim', explode(',', (string) $this->legacyWidget()->getKeywords()));
        return array_values(array_filter($aKeywords, 'strlen'));
    }

    // --------------------------------------------------------------------------

    public function getScreenshots(): array
    {
        $sScreenshot = (string) $this->legacyWidget()->getScreenshot();
        return $sScreenshot === '' ? [] : [$sScreenshot];
    }

    // --------------------------------------------------------------------------

    public function render(array $data): string
    {
        return (string) $this->legacyWidget()->render($data);
    }

    // --------------------------------------------------------------------------

    /** A bridge that overrides a v2 widget must not take that widget's canvas markup */
    public function preview(array $data, array $context = []): string
    {
        return $this->render($data);
    }

    // --------------------------------------------------------------------------

    /** The v1 widget reads its data as it was stored, so a v2 parent's upgrade() is not applied */
    public function upgrade(array $data): array
    {
        return $data;
    }

    // --------------------------------------------------------------------------

    /** The v1 form is the inspector, even when the bridge overrides a v2 widget with fields */
    public function getFields(): ?array
    {
        return null;
    }

    // --------------------------------------------------------------------------

    /** The v1 editor form, used as the HTML inspector */
    public function getEditorForm(array $data): ?string
    {
        return (string) $this->legacyWidget()->getEditor($data);
    }

    // --------------------------------------------------------------------------

    /** v1 render assets are not loaded in the canvas (D22), so only the editor assets are returned */
    public function getAssets(): array
    {
        return [
            'render' => [],
            'editor' => array_values((array) $this->legacyWidget()->getEditorAssets()),
        ];
    }

    // --------------------------------------------------------------------------

    /**
     * The v1 "dropped" and "removed" scripts, as source. The editor runs them (see legacy-callbacks.js).
     *
     * @return array{dropped: string, removed: string}
     */
    public function getCallbacks(): array
    {
        $oCallbacks = $this->legacyWidget()->getCallbacks();
        return [
            'dropped' => (string) ($oCallbacks->dropped ?? ''),
            'removed' => (string) ($oCallbacks->removed ?? ''),
        ];
    }
}
